/// <summary>
/// CB434, Extension class for table <c>InventItemPrice</c>
/// </summary>
[ExtensionOf(tableStr(InventItemPrice))]
internal final class METInventItemPrice_Extension
{
}

Method.Source:
    /// <summary>
    /// CB434, stop standard logic from overwriting Activation date, it should be defined from Base price From Date
    /// </summary>
    /// <returns>TransDate activation date</returns>
    protected TransDate initialActivationDate()
    {
        TransDate   activationDate;

        activationDate = next initialActivationDate();
        if (this.ActivationDate)
        {
            activationDate = this.ActivationDate;
        }
        return activationDate;
    }

    /// <summary>
    /// find previous standard cost price
    /// </summary>
    /// <param name = "_itemId"></param>
    /// <param name = "_inventDimId"></param>
    /// <param name = "_activationDate"></param>
    /// <returns></returns>
    public static InventItemPrice metSTDCostFindPrev(
        ItemId           _itemId,
        InventDimId      _inventDimId,
        TransDate       _activationDate
        )
    {
        InventItemPrice         preInventItemPrice;

        if (InventDim::find(_inventDimId).isOwnerCurrentLegalEntity())
        {
            InventTable inventTable     = InventTable::find(_itemId);
            InventDim inventDimCriteria = InventItemPrice::initializeInventDimCriteria(inventTable, _inventDimId);
            InventDim inventDim         = InventDim::findDim(inventDimCriteria);

            select firstonly reverse preInventItemPrice
                    order by ActivationDate
                    where preInventItemPrice.ItemId          == _itemId
                       && preInventItemPrice.ActivationDate <  _activationDate
                       && preInventItemPrice.PriceType       == CostingVersionPriceType::Cost
                       && preInventItemPrice.InventDimId     == inventDim.inventDimId;
        }

        return preInventItemPrice;
    }
